INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('4', NULL, 'NSBM Hockey Teams Earn Podium Finishes at KDU Leaders’ Trophy 2026', 'Sports', 'Faculty of Computing', 'NSBM Green University’s women’s and men’s hockey teams achieved podium finishes at the KDU Leaders’ Trophy 2026 Inter-University Sports Championship. The women’s team finished as first runner-up, while the men’s team secured second runner-up.\n\nThe teams were coached by Mr. Shanaka. Their performances highlighted the teamwork and preparation behind NSBM’s participation in the championship.', 'images/nsbm-hockey-kdu-2026.jpg', 'Article', 'approved', '', NULL, '2026-10-19 00:00:00');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('13', NULL, 'NSBM Celebrates Its 10th Anniversary', 'General', 'Faculty of Computing', 'NSBM Green University marked its tenth anniversary on 26 October 2026 with a ceremony at its auditorium in Homagama. The event brought together international university representatives, industry partners, alumni and other invited guests.\n\nThe celebration included a partnership agreement with Zhejiang Shuren University in China. A commemorative stamp, the Vision to Legacy magazine and an economic impact report covering 2016–2026 were also launched.\n\nNSBM NEXT, a roadmap for the coming decade, outlined the university’s future direction in higher education and international collaboration.', 'images/nsbm-10th-anniversary.jpg', 'Article', 'approved', '', NULL, '2026-10-26 00:00:00');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('14', NULL, 'NSBM Opens Rs. 720 Million Civil Engineering Laboratory Complex', 'General', 'Faculty of Engineering', 'NSBM Green University opened its new Civil Engineering Laboratory Complex on 26 October 2026 during its tenth anniversary celebrations. The university funded the Rs. 720 million investment in practical engineering education.\n\nLocated at the Phase II development in Pitipana, Homagama, the complex provides laboratories and learning facilities to support hands-on training and industry-relevant engineering skills.\n\nAttorney General K. A. Parinda Ranasinghe Jr. ceremonially opened the complex. The development forms part of NSBM’s wider programme to expand its academic infrastructure.', 'images/nsbm-civil-opening.jpg', 'Article', 'approved', '', NULL, '2026-10-26 00:00:00');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('15', NULL, 'NSBM Unveils Proposed Medical and Research Hospital Model', 'General', 'Faculty of Computing', 'NSBM Green University unveiled the architectural model for a proposed multibillion-rupee Medical and Research Hospital on 26 October 2026, during its tenth anniversary celebrations.\n\nThe project is planned for a 20-acre site opposite the university in Pitipana, Homagama, as part of its Phase III expansion. Proposed services include inpatient and outpatient care, diagnostics, wellness services and research-based healthcare.\n\nThe initiative forms part of NSBM NEXT, the university’s vision for its next decade, connecting healthcare, research, science and technology. The announcement concerns a proposed hospital and the unveiling of its model.', 'images/nsbm-hospital-model.jpg', 'Article', 'approved', '', NULL, '2026-10-26 00:00:00');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('16', NULL, 'NSBM Faculty of Science Celebrates Its Fourth Anniversary', 'General', 'Faculty of Science', 'The Faculty of Science at NSBM Green University celebrated its fourth anniversary on 28 April 2026 at the university auditorium. Academics, industry representatives and students gathered to mark the faculty’s progress.\n\nThe programme included a formal session called SciVision ’26, bringing the faculty community together to celebrate its achievements and engage in discussions. University leaders and representatives from several faculties attended the event.', 'images/nsbm-science-anniversary.jpg', 'Article', 'approved', '', NULL, '2026-05-04 00:00:00');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('17', NULL, 'Team Phoenix Wins NSBM Inter Batch 4.0 Chess Tournament', 'Sports', 'Faculty of Computing', 'More than 60 students took part in Inter Batch 4.0, the NSBM Chess Club’s largest inter-batch tournament to date, according to the university’s report published on 16 September 2026.\n\nTeam Phoenix (26.1) took first place, followed by Team A (26.2) in second and Team Apex (26.1) in third. The competition gave students an opportunity to demonstrate their strategy, concentration and sportsmanship through a series of closely contested matches.', 'images/nsbm-chess-interbatch.jpg', 'Article', 'approved', '', NULL, '2026-09-16 00:00:00');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('18', NULL, 'NSBM Retains KDU Inter-University T20 Cricket Championship', 'Sports', 'Faculty of Computing', 'NSBM won the KDU Leaders’ Trophy Inter-University T20 Cricket Championship 2026, completing the tournament unbeaten and securing a second consecutive inter-university cricket title.\n\nIn the final, NSBM restricted SLIIT to 130/9. Punsara Rajakaruna took three wickets for 23 runs. Ushen Silva’s unbeaten 63 and Lahiru Abeysinghe’s 44 off 21 balls helped NSBM reach the target with five wickets and nine deliveries remaining.\n\nUshen Silva received the Player of the Final award, while Amoda Vidanapathirana was named Player of the Tournament after contributing 169 runs and three wickets across four matches.', 'images/nsbm-cricket-champions-2026.jpg', 'Article', 'approved', '', NULL, '2026-09-10 00:00:00');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('19', NULL, 'NSBM Drama Club Presents Megha 26', 'Events', 'Faculty of Computing', 'NSBM Drama Club presented a 2026 stage event, featured in a post by the official NSBM Green University Facebook page. The shared performance clip shows dancers in traditional costumes performing on a decorated stage.', 'images/nsbm-megha-26.jpg', 'Article', 'approved', '', NULL, '2026-11-02 05:25:05');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('20', NULL, 'NSBM Hosts Palliative Care Nursing Workshop for Final-Year Undergraduates', 'Academic', 'Faculty of Science', 'The Department of Health Sciences, Faculty of Science at NSBM Green University, held a Palliative Care Nursing Workshop for final-year nursing undergraduates on 14 October 2026. The workshop formed part of the Palliative and Geriatric Care Nursing module.\n\nThe sessions focused on holistic, compassionate and patient-centred care. Topics included patient assessment, pain and symptom management, non-pharmacological pain relief, end-of-life and bereavement care, and therapeutic communication.\n\nThe facilitators were Ms. Samindra Ranasinghe, Palliative Care Master Trainer and Matron of Shantha Sevena Hospice; Ms. Priyanka Kasthuriarachchi, Palliative Care Master Trainer at the National Institute of Cancer; Ms. Ajitha Nimali, Nurse-in-Charge of its Pain Management Unit; and Ms. W. A. K. Kumari, Nursing Officer at its Palliative Care Unit.\n\nMs. Sandyani de Silva, Senior Grade Nursing Tutor and Programme Coordinator of the B.Sc. (Hons) Nursing Degree Programme at NSBM, facilitated the learning opportunity and connected students with the visiting professionals.\n\nThe initiative supported clinical learning and the preparation of future nurses to deliver dignified, evidence-based care.', 'images/nsbm-palliative-nursing-workshop.jpg', 'Article', 'approved', '', NULL, '2026-10-14 00:00:00');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('21', NULL, 'NSBM Orientation Day Two Focuses on Personal Development and Wellbeing', 'Academic', 'Faculty of Computing', 'The second day of NSBM Green University’s new intake orientation programme focused on personal development, ethical responsibility and mental health.\n\nThe university shared highlights of the programme on its official Facebook page.', 'images/nsbm-orientation-day-two.jpg', 'Article', 'approved', '', NULL, '2026-11-02 15:31:50');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('22', NULL, 'NSBM Hosts Critical Literature Review Workshop for PhD Students', 'Academic', 'Faculty of Postgraduate and Professional Advancement', 'NSBM Green University’s Faculty of Postgraduate and Professional Advancement hosted a two-day Critical Literature Review workshop for PhD students, facilitated by Dr. Payal Kumar, Principal Academic Advisor at the Indian School of Hospitality, India. The sessions helped doctoral researchers explore critical engagement with scholarly literature and its role in rigorous research.\n\nDrawing on her experience in research, academic publishing and scholarly reviewing, Dr. Kumar discussed how to develop a critical approach to literature reviews. She emphasised thoughtful analysis and scholarly engagement as foundations for doctoral study.\n\nMaster of Education students also engaged with Dr. Kumar’s insights and considered their relevance to postgraduate study and educational research. Newly admitted PhD students met her as well, gaining an early opportunity to connect with an experienced scholar at the start of their doctoral journey.', 'images/nsbm-literature-review-workshop.jpg', 'Article', 'approved', '', NULL, '2026-11-02 15:34:04');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('23', NULL, 'NSBM Corporate Readiness Workshop Explores AI for Students', 'Academic', 'Faculty of Business', 'The Department of Accounting and Finance at NSBM Green University conducted Session 04 of its Corporate Readiness Workshop Series for Batch 25.1 students under the theme “AI for Students”.\n\nThe session was facilitated by Mr. Charith Gunasekara, CFA, Associate Director at Uzabase Sri Lanka. He introduced students to the potential of Artificial Intelligence to enhance learning, improve productivity and help them navigate an evolving professional landscape.\n\nStudents explored how to use AI tools effectively and responsibly to support their academic work and prepare for the demands of the modern workplace.\n\nThe department expressed its appreciation to Mr. Charith Gunasekara and Uzabase Sri Lanka for supporting the development of students’ digital skills and professional readiness.', 'images/nsbm-ai-for-students.jpg', 'Article', 'approved', '', NULL, '2026-11-02 15:36:47');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('24', NULL, 'NSBM Engineering Undergraduates Participate in Techno 2026', 'Academic', 'Faculty of Engineering', 'Undergraduate students from the Faculty of Engineering at NSBM Green University participated in Techno 2026, the 38th National Engineering and Technology Exhibition organised by the Institution of Engineers, Sri Lanka (IESL).\n\nUnder the theme “Engineering for a Resilient Nation”, the exhibition provided a platform to explore engineering innovations, emerging technologies and practical solutions to real-world challenges.\n\nThe experience encouraged students to broaden their knowledge, exchange ideas and discover new possibilities for a more innovative and sustainable future. It also gave them an opportunity to engage with Sri Lanka’s engineering and technology community as they prepare for their future careers.\n\nNSBM expressed its pride in its undergraduates’ participation and commitment to innovation and the future of engineering.', 'images/nsbm-techno-2026.jpg', 'Article', 'approved', '', NULL, '2026-11-02 15:40:09');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('25', NULL, 'NSBM Computing Faculty Launches FIT Programme Session Two', 'Academic', 'Faculty of Computing', 'The Faculty of Computing at NSBM Green University launched the second session of the NSBM FIT (Future Innovation & Technology) Programme for Plymouth Batch 13 final-year Computing students, connecting them with industry knowledge and emerging technologies.\n\nThe session featured IFS experts Mr. Sujith Wijerathna, Senior Director, Software Engineering; Mr. Chamath De Silva, Principal DevOps Engineer; and Mr. Nuwan Ranasinghe, Senior DevOps Engineer. Drawing on their professional experience, the session focused on cloud technologies, DevOps practices, automation, modern software deployment and real-world software engineering workflows.\n\nMs. Pavithra Subhashini, Head of the Industry Collaboration Unit, Faculty of Computing, and Mr. Diluka Wijesinghe, Course Director for Plymouth Computing Degree Programmes, attended the event. Their participation reflected the faculty’s commitment to industry–academic partnerships and industry-relevant learning.\n\nThrough the FIT Programme, the Faculty of Computing aims to equip future professionals with practical perspectives, technical knowledge and industry exposure for a rapidly evolving technology sector.', 'images/nsbm-fit-session-two.jpg', 'Article', 'approved', '', NULL, '2026-11-02 15:43:45');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('26', NULL, 'NSBM Dance and Aerobics Club Announces Kinetic Fire ’26', 'Events', 'Faculty of Computing', 'The NSBM Dance and Aerobics Club has announced KINETIC FIRE ’26, a celebration of dance bringing together tradition, rhythm and expressive performance.\n\nThe club shared the event announcement on its official Facebook page, inviting audiences to look forward to the showcase.', 'images/nsbm-kinetic-fire-26.jpg', 'Article', 'approved', '', NULL, '2026-11-02 15:49:41');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('27', NULL, 'NSBM Dance and Aerobics Club Presents THRI-ANTHA', 'Events', 'Faculty of Computing', 'The NSBM Dance and Aerobics Club announced THRI-ANTHA, presenting it as a story of love and an emotional journey for audiences.\n\nThe club shared a preview of the production on its official Facebook page.', 'images/nsbm-thri-antha.jpg', 'Article', 'approved', '', NULL, '2026-11-02 15:51:45');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('28', NULL, 'NSBM Literature Circle Hosts RANGAHALA ’26', 'Events', 'Faculty of Computing', 'RANGAHALA ’26, organised by the NSBM Literature Circle, was held on 9 July 2026 at the NSBM Open Air Theater. Under the theme “Echoes Through Time”, the event celebrated the evolution of Sri Lankan performance and literary arts through an evening of culture, creativity and entertainment.\n\nOne of the Literature Circle’s signature events, the celebration brought together an enthusiastic audience. Renowned musician Suneera Sumanga joined as Guest Artist, adding special performances to the evening.\n\nThe occasion was attended by Prof. E. A. Weerasinghe, Vice Chancellor; Prof. Chaminda Rathnayaka, Senior Deputy Vice Chancellor; Dr. Thilini D. Silva, Deputy Vice Chancellor – Academic; and Prof. Bharatha Dodankotuwa, Head of Academic Development and Quality Assurance, alongside academic and non-academic staff.\n\nThe organisers acknowledged the guidance and support of the Literature Circle’s Masters-in-Charge, Mr. Praveen Ranaweera and Mr. Savindu Damsara, whose leadership and encouragement helped make the event a success. Appreciation was also extended to all members of the NSBM Literature Circle.', 'images/nsbm-rangahala-26.jpg', 'Article', 'approved', '', NULL, '2026-07-09 00:00:00');
INSERT INTO `articles` (`id`, `user_id`, `title`, `category`, `faculty`, `body`, `image`, `format`, `status`, `feedback`, `expires`, `created_at`) VALUES ('29', NULL, 'NSBM Marks Its Tenth Anniversary with Overnight Pirith Chanting', 'General', 'Faculty of Computing', 'An overnight Pirith Chanting Ceremony was held on 23 October 2026 at the newly constructed NSBM Civil Engineering Laboratory premises as part of the religious observances marking NSBM Green University’s tenth anniversary.\n\nThe ceremony invoked the blessings of the Triple Gem upon the NSBM community, including staff, students, alumni and parents, and sought blessings for the university’s continued progress and future endeavours.\n\nA traditional procession escorted the venerable Maha Sangha to the decorated Pirith Mandapaya, accompanied by traditional drummers and flag-bearers.\n\nAttendees included Vice Chancellor Prof. E. A. Weerasinghe; Senior Deputy Vice Chancellor Prof. Chaminda Rathnayake; Deputy Vice Chancellor – Academic Prof. Thilini De Silva; Head of Academic Development and Quality Assurance Prof. Baratha Dodankotuwa; faculty deans; heads of departments; academic and non-academic staff; and students.', 'images/nsbm-pirith-ceremony-cover.jpg', 'Article', 'approved', '', NULL, '2026-10-23 00:00:00');
